"""Original Russian glossary and command cards for the Git/build volume.

Examples that change history or delete files assume a disposable lab repository.
No command from this module is executed by importing it.
"""

GLOSSARY = [
    ('Git', 'Распределённая система контроля версий, сохраняющая объекты содержимого и ссылки на историю. Обычная локальная копия позволяет создавать коммиты и сравнивать сохранённые версии без обращения к серверу.'),
    ('Репозиторий', 'Хранилище объектов проекта, ссылок на историю и служебных настроек. Рабочие файлы могут находиться рядом с ним, но сами по себе ещё не являются сохранённой историей.'),
    ('Рабочее дерево', 'Файлы и каталоги, с которыми непосредственно работает человек или программа сборки. Их содержимое может отличаться как от последнего коммита, так и от подготовленной к следующему коммиту версии.'),
    ('Индекс Git', 'Служебное описание подготовленного состояния файлов для следующего коммита. Команда add обновляет выбранные записи индекса; дальнейшее редактирование рабочих файлов не обновляет их автоматически.'),
    ('HEAD', 'Ссылка, определяющая текущую позицию работы в истории. Обычно она указывает на имя ветки, а при отделённом состоянии — непосредственно на коммит.'),
    ('Снимок Git', 'Логически полное состояние отслеживаемых файлов, описанное деревом коммита. Это не обязательно отдельная физическая копия каждого файла: одинаковые объекты переиспользуются.'),
    ('Отслеживаемый файл', 'Файл, имеющий запись в индексе Git. Его сохранённая версия, подготовленная версия и текущие рабочие байты могут различаться.'),
    ('Неотслеживаемый файл', 'Рабочий файл, ещё не включённый в индекс. Он не попадёт в обычный коммит, пока его явно не подготовят, а восстановление сохранённой истории не гарантирует возврата его содержимого.'),
    ('Blob', 'Объект Git, содержащий последовательность байтов файла без его имени и расположения. Имя связывается с этим объектом через запись дерева, поэтому одинаковое содержимое разных файлов может использовать один объект.'),
    ('Tree', 'Объект Git, связывающий имена с типами, режимами и идентификаторами файлов или подкаталогов. Коммит ссылается на корневое дерево, через которое описывается состояние проекта.'),
    ('Коммит', 'Объект, связывающий корневое дерево проекта, родительские коммиты, сведения об авторе и сообщение. Ветка указывает на коммит, а следующий коммит обычно продолжает историю от текущей позиции.'),
    ('OID', 'Object identifier — идентификатор объекта Git, полученный хешированием его типизированного содержимого. При изменении содержимого или значимых метаданных он вычисляется заново; сокращённую запись используют только при отсутствии неоднозначности.'),
    ('Адресация по содержимому', 'Способ называть данные через результат вычисления по их собственным байтам. В Git при вычислении учитываются также тип и длина объекта, а не только отображаемый текст файла.'),
    ('SHA-1', 'Хеш-функция, выдающая 160 бит, обычно записываемых сорока шестнадцатеричными знаками. В репозитории соответствующего формата Git использует такой идентификатор объектов; сам хеш не удостоверяет личность автора.'),
    ('SHA-256', 'Хеш-функция с результатом в 256 бит, обычно представляемых шестьюдесятью четырьмя шестнадцатеричными знаками. Формат объектов Git и внешняя контрольная сумма сборки выбираются отдельно: использование SHA-256 для ZIP не меняет формат репозитория.'),
    ('Loose object', 'Объект Git, хранящийся отдельно от упаковочных файлов. Такое представление удобно для добавления новых объектов, а обслуживание репозитория может позднее упаковать их совместно.'),
    ('Packfile', 'Файл Git, содержащий несколько упакованных объектов. Некоторые объекты могут храниться через отличия от базовых, но логическая модель сохранённых состояний проекта от этого не меняется.'),
    ('Delta compression', 'Экономия места через описание отличий одного объекта от другого. Для получения исходных байтов нужно восстановить базу и применить отличие; длинная цепочка может увеличить работу чтения.'),
    ('Pathspec', 'Выражение Git, ограничивающее набор путей, к которым относится команда. Оно обрабатывается Git после передачи аргументов оболочкой, поэтому правила выбора путей нельзя автоматически считать правилами Bash.'),
    ('Стадия индекса', 'Номер записи индекса, позволяющий во время конфликта сохранить несколько версий одного пути. Для обычного трёхстороннего слияния используются общий предок и две стороны; после разрешения остаётся обычная запись стадии ноль.'),
    ('Stat cache', 'Сохранённые в индексе сведения о свойствах рабочего файла, помогающие Git быстрее проверять возможные изменения. Они ускоряют наблюдение, но не заменяют модель содержимого файла в объектном хранилище.'),
    ('DAG', 'Направленный ациклический граф: структура с направленными связями, в которой нельзя пройти по ним и вернуться в исходную вершину. Коммиты Git связаны с родителями таким графом; порядок строк журнала является лишь способом его показа.'),
    ('Родитель коммита', 'Коммит, на который новый коммит ссылается как на предыдущее состояние истории. Обычный коммит имеет одного родителя, начальный не имеет родителей, а результат слияния может иметь нескольких.'),
    ('Достижимость', 'Возможность найти объект, проходя по связям от выбранных исходных ссылок или объектов. Недостижимость из одной ветки не означает удаления: объект может сохраняться через другую ветку, метку или журнал ссылок.'),
    ('Диапазон ревизий', 'Правило выбора коммитов через включение и исключение достижимой истории. Одинаково выглядящие обозначения в log и diff имеют разный смысл: просмотр множества коммитов и сравнение двух состояний требуют различать.'),
    ('Ветка Git', 'Изменяемая ссылка на коммит, от которого продолжается отдельная линия работы. Создание ветки не создаёт самостоятельную физическую копию всех файлов проекта.'),
    ('Символическая ссылка Git', 'Служебная ссылка Git, содержащая имя другой ссылки вместо непосредственного идентификатора объекта. Обычная HEAD использует этот механизм; он отличается от символических ссылок файловой системы.'),
    ('Detached HEAD', 'Состояние, в котором HEAD указывает непосредственно на коммит, не следуя имени ветки. Новые коммиты можно создавать, но перед уходом полезно дать нужной истории собственную ветку.'),
    ('Unborn branch', 'Состояние именованной ветки до появления её первого коммита. HEAD уже может содержать имя ветки, однако ссылки на существующий коммит под этим именем ещё нет.'),
    ('Upstream', 'Настроенная для локальной ветки исходная ветка, с которой Git связывает некоторые сравнения, получение и объединение изменений. Это настройка отношений ссылок, а не универсальное название конкретного сервера.'),
    ('Diff', 'Представление различий между двумя выбранными состояниями содержимого. Пустой результат говорит об этих двух состояниях, а не об отсутствии любых изменений во всём репозитории.'),
    ('Hunk', 'Участок текстового различия, объединяющий соседние изменения и окружающие строки. При частичной подготовке можно выбирать такие участки, сохраняя в индексе только часть работы.'),
    ('Контекст различия', 'Неизменённые строки вокруг изменённого участка, показанные для понимания его положения. Их количество влияет на читаемость и размер представления, но не меняет сами сравниваемые состояния.'),
    ('Merge base', 'Общий предок, выбранный Git как основа сравнения двух линий истории. При сложном графе общих подходящих предков может быть несколько, поэтому слияние не всегда сводится к сравнению с одной очевидной вершиной.'),
    ('Трёхстороннее слияние', 'Построение результата по общей исходной версии и двум независимо изменённым состояниям. Конфликт возникает, когда выбранные правила не позволяют автоматически согласовать изменения.'),
    ('Fast-forward', 'Продвижение ссылки ветки к коммиту, уже продолжающему её текущую историю. Отдельный коммит объединения при этом не нужен, потому что существующая история уже содержит обе стороны.'),
    ('Конфликт слияния', 'Состояние, требующее решения о совместном результате изменений. Маркеры в рабочем файле и несколько стадий индекса помогают исследовать стороны, но их механическое удаление не доказывает правильность программы.'),
    ('Merge commit', 'Коммит, сохраняющий результат объединения и несколько родительских связей. Порядок родителей значим для некоторых операций, например выбора основной линии при отмене слияния.'),
    ('Ours и theirs', 'Названия сторон, используемые отдельными операциями Git при выборе версии конфликтного пути. Во время переигрывания коммитов rebase их смысл может отличаться от привычного «моя ветка и чужая ветка», поэтому сначала проверяют сами версии.'),
    ('Rebase', 'Переигрывание изменений выбранной последовательности коммитов поверх другой исходной позиции. Полученные коммиты обычно имеют новые идентификаторы, поскольку меняются родители и другие элементы их содержимого.'),
    ('Revert', 'Создание нового коммита с изменением, отменяющим эффект выбранного старого изменения в текущем состоянии. Старый коммит остаётся частью истории, а применение обратного изменения может потребовать разрешения конфликта.'),
    ('Reset', 'Семейство операций Git, меняющих выбранные состояния ссылки, индекса и иногда рабочих файлов. Режим и форма команды определяют затрагиваемые области; слово reset само по себе не объясняет, что будет потеряно.'),
    ('Cherry-pick', 'Применение изменения выбранного коммита к текущей линии работы с созданием нового коммита. Это не перенос прежней вершины графа без изменений: новый родитель обычно означает другой идентификатор.'),
    ('Переписывание истории', 'Замена видимой через ссылки последовательности коммитов другой последовательностью. Если прежние коммиты уже использовали другие люди, их локальные ссылки не изменятся автоматически и потребуют согласования.'),
    ('Reflog', 'Локальный журнал прежних положений отдельных ссылок и HEAD. Он помогает найти недавно оставленную историю, но имеет правила очистки и не является бессрочным удалённым резервом.'),
    ('Недостижимый объект', 'Существующий объект, до которого нельзя дойти от выбранного набора корневых ссылок. Его судьба зависит от журналов, возраста и обслуживания; отсутствие имени ветки не означает немедленного физического удаления.'),
    ('Dangling object', 'Объект на свободном конце исследуемой недостижимой цепочки, на который не ссылаются другие рассматриваемые объекты. Такая вершина может помочь восстановлению; полезные предшествующие объекты могут находиться за ней по связям.'),
    ('Garbage collection', 'Обслуживание хранилища Git, включающее упаковку и действия по очистке ненужных объектов согласно настройкам. Упаковка ради экономии места и окончательное удаление данных — разные действия, последствия которых следует учитывать отдельно.'),
    ('Prune', 'Удаление подходящих недостижимых объектов с учётом выбранных правил возраста. Уменьшение временного запаса может сократить возможность восстановления и требует учитывать параллельную запись в репозиторий.'),
    ('Remote', 'Именованная настройка другого репозитория: его адресов и правил обмена ссылками. Само имя origin не доказывает ни место расположения, ни доверие к получателю.'),
    ('Remote-tracking branch', 'Локальная ссылка, сохраняющая полученное Git представление о ветке другого репозитория. Обычный fetch обновляет её, но не обязан переключать вашу локальную ветку и рабочие файлы.'),
    ('Refspec', 'Правило соответствия исходных и целевых ссылок при обмене между репозиториями. Явная запись помогает понять, какая ветка передаётся и какое имя изменится у получателя.'),
    ('Fetch', 'Получение нужных объектов и обновление настроенных ссылок о другой стороне. Это отдельное действие от включения полученной истории в текущую рабочую ветку.'),
    ('Push', 'Предложение другому репозиторию принять объекты и обновить указанные ссылки. Доступный транспорт не гарантирует разрешения на изменение ветки: получатель дополнительно проверяет права и правила обновления.'),
    ('Pull', 'Команда, объединяющая получение изменений с последующим включением их в текущую линию работы. Способ включения зависит от явных параметров и настроек, поэтому перед применением важно понимать выбранное слияние или переигрывание.'),
    ('Bare repository', 'Репозиторий без обычного рабочего дерева для редактирования проекта. Его удобно использовать как общую точку обмена; отсутствие рабочих файлов не означает отсутствия содержимого в объектах.'),
    ('Pull request', 'Предложение объединить изменение, оформленное средствами площадки размещения репозитория. Комментарии, проверки и правила принятия принадлежат площадке, тогда как сами коммиты и ссылки остаются объектами Git.'),
    ('Code review', 'Проверка изменения другим участником с обсуждением корректности, понятности и последствий. Автоматические тесты дают часть свидетельств, но не заменяют понимание требований и границ изменения.'),
    ('Non-fast-forward', 'Обновление ссылки, которое не является простым продвижением по продолжающейся истории. Отказ при обычной отправке защищает ранее опубликованную линию от незаметной замены другой.'),
    ('Force-with-lease', 'Условие принудительного обновления ссылки только при ожидаемом прежнем состоянии получателя. Явное ожидаемое значение делает проверку понятнее; простая форма может зависеть от локальных ссылок, обновляемых фоновым получением.'),
    ('Credential helper', 'Механизм передачи Git данных доступа через отдельную программу хранения или получения учётных данных. Он не определяет права на ветку и не должен смешиваться с настройками имени автора коммита.'),
    ('.gitignore', 'Файл правил исключения некоторых неотслеживаемых путей из обычного показа и подготовки. Уже отслеживаемый файл не исчезает из истории после добавления такого правила.'),
    ('.gitattributes', 'Файл правил свойств путей Git, влияющих на обработку содержимого, сравнение и другие операции. Они позволяют задавать поведение для конкретных файлов, а не полагаться только на личную конфигурацию пользователя.'),
    ('Clean filter', 'Преобразование содержимого при подготовке файла в Git. Оно может сделать сохранённые байты отличными от рабочих, поэтому при исследовании идентификаторов объектов учитывают применённые атрибуты и фильтры.'),
    ('Smudge filter', 'Преобразование при получении рабочего файла из сохранённого представления. Доступность и версия преобразователя становятся частью условий восстановления рабочей копии.'),
    ('LF', 'Перевод строки одним байтом с кодом 10 в обычном текстовом представлении. Изменение способа завершения строк меняет байты файла, даже если редактор показывает почти одинаковые строки.'),
    ('CRLF', 'Завершение строки парой байтов с кодами 13 и 10. Преобразование между этим представлением и LF может задаваться атрибутами и настройками Git; его следует отличать от изменения смысла исходного кода.'),
    ('Renormalization', 'Повторная подготовка отслеживаемых файлов с действующими правилами нормализации содержимого. Такое изменение полезно отделять от функциональных правок, чтобы проверяющий мог понять причину большого различия.'),
    ('Git LFS', 'Large File Storage — расширение для хранения крупных файлов, оставляющее в обычной истории Git небольшой указатель на отдельно размещённое содержимое. Наличие указателя не гарантирует доступности самих данных при автономном восстановлении.'),
    ('Commit-graph', 'Дополнительная структура Git, ускоряющая некоторые запросы по связям коммитов. Она помогает обходить историю, но не заменяет сами коммиты как источник сохранённых данных.'),
    ('Bitmap index', 'Структура с битовыми наборами, ускоряющая определение достижимости групп объектов. Польза зависит от формы истории и выполняемых операций, поэтому наличие индекса само по себе не является измерением ускорения.'),
    ('Shallow clone', 'Копия репозитория с ограниченной глубиной истории и отмеченными границами обхода. Она экономит первоначальное получение, но некоторые исследования предков требуют догрузки отсутствующей истории.'),
    ('Partial clone', 'Копия, в которой часть объектов намеренно не загружена заранее и может запрашиваться позже. Для автономной работы важно проверить наличие нужных объектов, а не только успешное создание каталога.'),
    ('Build', 'Процесс превращения выбранных исходных данных в объявленный результат: программу, пакет или набор файлов. Инструменты, параметры, окружение и зависимости влияют на результат вместе с исходниками.'),
    ('Артефакт сборки', 'Результат, который предполагается сохранить, проверить или передать дальше после сборки. Временные файлы и журналы могут быть полезны, но не обязаны входить в состав поставляемого артефакта.'),
    ('Граф сборки', 'Описание целей и зависимостей, задающее допустимый порядок работы. Параллельное выполнение корректно только тогда, когда нужные зависимости описаны, а общие изменяемые файлы учтены.'),
    ('Рецепт make', 'Команды, выполняемые для получения конкретной цели при выполнении условий правила. Они запускаются оболочкой, поэтому её аргументы, перенаправления и коды завершения продолжают иметь значение.'),
    ('PHONY', 'Объявление make, что указанная цель обозначает действие, а не обычный файл с таким именем. Оно предотвращает ситуацию, когда случайный одноимённый файл отменяет нужный запуск действия.'),
    ('Инкрементальная сборка', 'Повторное получение результата с переиспользованием подходящих ранее построенных частей. Ошибочно пропущенная зависимость может дать быстрый, но устаревший результат.'),
    ('Окружение сборки', 'Инструменты, переменные, доступные файлы и другие условия исполнения процесса сборки. Для проверки воспроизводимости нужно явно определить, какие из этих условий существенны.'),
    ('Зависимость сборки', 'Внешний или внутренний компонент, необходимый для получения результата. Его имя без точной версии и способа получения может оказаться недостаточным описанием входа.'),
    ('Транзитивная зависимость', 'Компонент, который нужен выбранной зависимости, хотя проект не перечисляет его как прямой. Изменение промежуточного выбора версий может изменить итоговую поставку без правки прикладного исходника.'),
    ('Maven', 'Инструмент сборки, организующий работу проекта через описание POM, фазы и подключаемые средства выполнения. Передача фазы запускает относящиеся к ней действия по правилам жизненного цикла, а не просто одноимённый файл.'),
    ('POM', 'Project Object Model — описание проекта Maven, его координат, зависимостей и настроек сборки. Итоговая конфигурация может учитывать наследование и профили, поэтому один видимый фрагмент файла не всегда показывает все действующие параметры.'),
    ('Координаты артефакта', 'Набор полей, позволяющий системе зависимостей выбрать конкретный компонент, например группу, имя и версию Maven. Совпадение короткого имени не гарантирует совпадения полного компонента.'),
    ('Dependency resolution', 'Выбор конкретных версий и получение компонентов согласно правилам системы зависимостей. Результат зависит от объявлений проекта, доступных репозиториев и правил разрешения противоречий.'),
    ('Lockfile', 'Файл, закрепляющий выбранные версии и иногда контрольные суммы зависимостей в поддерживающей его системе. Его полезность зависит от того, действительно ли сборщик соблюдает закреплённые значения.'),
    ('Воспроизводимая сборка', 'Сборка, для которой при объявленных исходниках, окружении и инструкциях можно получить побайтно одинаковые указанные артефакты. Совпадение поведения программы или один успешный повтор не заменяют сравнение результата.'),
    ('Герметичная сборка', 'Сборка с ограниченным доступом к необъявленным внешним входам. Такая изоляция помогает контролировать зависимости, но сама по себе ещё не исключает случайность или время внутри вычисления.'),
    ('Детерминированность', 'Свойство получать один и тот же результат при одних и тех же значимых входах. Если время или случайное значение фактически используются, их нужно считать входами либо исключить их влияние.'),
    ('SOURCE_DATE_EPOCH', 'Согласованная переменная с отметкой времени в секундах, которую поддерживающие инструменты могут использовать вместо текущего времени сборки. Установка переменной не заставляет произвольную программу учитывать её.'),
    ('Provenance', 'Сведения о происхождении результата: исходниках, действиях и условиях его получения. Они помогают исследованию поставки, но должны сопоставляться с фактическими входами, особенно при изменённом рабочем дереве.'),
    ('ZIP_STORED', 'Метод записи данных ZIP без сжатия. При фиксированных входах и метаданных он позволяет исключить влияние разных реализаций сжатия на байты учебного архива.'),
    ('Кэш сборки', 'Хранилище результатов, которые можно повторно использовать при подходящих условиях сборки. Правильность выбора сохранённого результата зависит от полного описания влияющих входов.'),
    ('Ключ кэша сборки', 'Представление входов, по которому ищется ранее полученный результат. Если существенный параметр исключён из ключа, одинаковый ключ может ошибочно объединить разные вычисления.'),
    ('Инвалидация кэша', 'Признание сохранённого результата неподходящим для текущих условий. Причиной может быть изменение исходника, инструмента, зависимостей или правил формирования результата.'),
    ('Cache poisoning', 'Попадание в кэш результата, который затем ошибочно принимается как доверенный для другого запуска. При общем кэше важны не только совпадение ключа, но и происхождение записи и разделение прав.'),
    ('Cache hit', 'Нахождение сохранённого результата по заданному запросу к кэшу. Попадание полезно лишь при корректности выбранного результата и с учётом цены проверки и передачи.'),
    ('Jenkins', 'Система автоматизации, координирующая задания и их выполнение в подготовленных средах. Успешный запуск задания говорит о его объявленных проверках, а не автоматически о готовности приложения к эксплуатации.'),
    ('Jenkins controller', 'Управляющий компонент Jenkins, обслуживающий конфигурацию, планирование и координацию выполнения. Тяжёлая сборка может выполняться на других узлах, поэтому занятость управляющего процесса и исполнителей рассматривают отдельно.'),
    ('Jenkins agent', 'Среда, к которой Jenkins обращается для выполнения выделенных шагов. Это может быть отдельный процесс на машине или временная среда; набор доступных инструментов нужно подготовить явно.'),
    ('Executor', 'Выделяемое Jenkins место одновременного выполнения работы на узле. Увеличение числа таких мест не создаёт дополнительные процессор, память или пропускную способность диска.'),
    ('Очередь Jenkins', 'Задания, ожидающие подходящих условий и места выполнения. Задержка может возникать из-за занятости исполнителей, требований к метке узла или других ограничений, даже если сами команды работают быстро.'),
    ('Workspace', 'Рабочий каталог конкретного выполнения задания или рабочей копии. Файлы в нём не следует считать автоматически доступными на другом агенте либо неизменно сохранёнными после очистки.'),
    ('Jenkins Remoting', 'Механизм связи управляющего компонента Jenkins с удалёнными исполнителями и их процессами. Проблема этого соединения отличается от неуспешного теста, запущенного внутри уже работающего задания.'),
    ('Jenkinsfile', 'Файл с описанием конвейера Jenkins, который можно хранить рядом с исходниками. Изменение этого файла меняет правила выполнения, но применимость синтаксиса зависит от установленных компонентов Jenkins.'),
    ('Declarative Pipeline', 'Форма описания конвейера Jenkins с определённой структурой разделов, стадий и условий. Некоторые вычисления можно вынести в программные блоки, но правила верхнего уровня остаются отдельной частью модели.'),
    ('Scripted Pipeline', 'Форма задания конвейера Jenkins средствами программных конструкций Groovy и шагов Jenkins. Доступ к языку не отменяет ограничения исполнения и требования к сохраняемому состоянию конвейера.'),
    ('Stage', 'Именованный участок конвейера, помогающий организовать работу и её отображение. Название стадии не доказывает, что она выполняется в отдельном процессе, на отдельной машине или параллельно другим.'),
    ('Post actions', 'Действия Jenkins, выбираемые после выполнения конвейера или стадии по заданному условию результата. Они подходят для публикации отчёта и очистки, но ошибки самого завершающего действия тоже нужно учитывать.'),
    ('Credentials binding', 'Передача выбранных Jenkins учётных данных шагам выполнения через поддерживаемый механизм. Маскирование некоторых строк журнала не гарантирует отсутствия утечки через файлы, процессы или намеренно изменённую программу.'),
    ('Unit test', 'Автоматическая проверка поведения относительно небольшой выделенной части программы. Её границы определяются устройством теста и заменённых зависимостей, а не только именем каталога tests.'),
    ('Integration test', 'Проверка совместной работы нескольких компонентов через реальные либо подготовленные границы взаимодействия. Успех изолированной функции не гарантирует прохождения такой проверки.'),
    ('Статический анализ', 'Исследование исходного кода или его представления без обычного исполнения проверяемого приложения. Результат зависит от правил и модели анализатора; найденное предупреждение требует оценки причины и условий.'),
    ('JUnit XML', 'Распространённое XML-представление результатов автоматических тестов, понимаемое многими средствами интеграции. Публикация отчёта не запускает тесты задним числом и не заменяет проверку кода завершения команды.'),
    ('Archive artifacts', 'Действие сохранения выбранных файлов задания Jenkins для дальнейшего получения. Выбор путей и срок хранения определяют доступный результат; локальный файл в рабочем каталоге сам по себе ещё не сохранён таким способом.'),
    ('Stash Jenkins', 'Временная передача выбранных файлов между частями одного выполнения конвейера Jenkins. Этот механизм следует отличать от git stash и от долговременного хранилища выпущенных артефактов.'),
    ('Fingerprint Jenkins', 'Запись контрольного отпечатка файла для отслеживания его использования в заданиях Jenkins. Она помогает связывать результаты между запусками, но не является криптографической подписью производителя.'),
    ('Критический путь', 'Последовательность зависимых действий, определяющая нижнюю границу времени завершения всего графа работ. Ускорение задачи вне этого пути может не уменьшить наблюдаемое время всей сборки.'),
    ('Пропускная способность сборок', 'Количество завершённых работ за выбранный промежуток времени. Её сравнивают при известном составе работ и отдельно от времени ожидания одного конкретного задания.'),
    ('Перцентиль задержки', 'Значение, ниже которого лежит указанная доля наблюдений времени выполнения. Для интерпретации нужны размер выборки, окно наблюдения и способ учёта ошибок и незавершённых запросов.'),
    ('Утилизация исполнителя', 'Доля выбранного времени, в течение которой выделенное место выполнения считается занятым. Это не то же самое, что загрузка процессора: занятая работа может ждать диск или внешний ответ.'),
    ('Flaky test', 'Проверка, дающая разные результаты без соответствующего намеренного изменения проверяемого поведения. Причинами могут быть время, порядок, общие данные или внешняя зависимость; простой повтор скрывает симптом, но не устраняет причину.'),
    ('Контрольная точка стенда', 'Известное учебное состояние, которое тренажёр умеет создать заново. Это не автоматическая резервная копия собственного решения читателя: восстановление может заменить его промежуточную работу.'),
    ('Маркер стенда', 'Служебная запись, позволяющая программе отличать созданный ею учебный каталог от произвольной папки. Проверка маркеров и дочерних путей ограничивает область сброса; подмена маркера не является способом ремонта личного проекта.'),
    ('Stateful стенд', 'Учебная среда, сохраняющая изменения между последовательными упражнениями. Повторный просмотр состояния не возвращает её к началу; сброс выполняется отдельным явным действием.'),
    ('Fixture', 'Подготовленные данные и условия, на которых выполняется конкретная проверка. Полезная проверка должна объяснять, какое свойство она исследует и почему выбранные условия позволяют заметить ошибку.'),
    ('Релиз', 'Выбранная для передачи пользователю версия приложения вместе с необходимыми результатами и сведениями о поставке. Создание метки Git может обозначить исходную точку, но само по себе не собирает и не развёртывает приложение.'),
    ('SBOM', 'Software Bill of Materials — перечень программных компонентов, входящих в поставку, с данными для их идентификации. Он помогает исследовать зависимости, но полнота и точность перечня требуют отдельной проверки.'),
    ('Цифровая подпись', 'Криптографическое свидетельство, связывающее подписанные данные с соответствующим ключом. Для вывода о производителе нужно проверить не только математическую корректность, но и доверие к ключу и выбранным данным.'),
    ('Контрольная сумма', 'Значение, вычисленное по байтам для проверки их совпадения с ожидаемыми. Если сам ожидаемый хеш получен из недоверенного источника, его совпадение не устанавливает доверие к поставке.'),
    ('Неизменяемый артефакт', 'Результат поставки, байты которого не заменяют под прежним именем версии после публикации. Такая договорённость облегчает проверку и откат, но требует правил хранения и контроля изменений.'),
    ('CI', 'Continuous Integration — непрерывная интеграция изменений с частой проверкой их совместной работы. Автоматический конвейер поддерживает этот процесс, но редкое объединение больших веток не становится частой интеграцией только из-за наличия сервера проверок.'),
    ('JDK', 'Java Development Kit — набор средств разработки Java, включающий компилятор и средства запуска. Версия, используемая сборщиком, должна согласовываться с требованиями проекта и среды исполнения результата.'),
    ('JVM', 'Java Virtual Machine — среда выполнения программ в формате байтового кода Java. Она управляет исполнением и памятью процесса; совместимость байтового кода и доступных библиотек нужно проверять отдельно от успешного создания архива.'),
    ('JAR', 'Java Archive — формат упаковки файлов на основе ZIP, часто содержащий классы и ресурсы Java. Архив не обязательно запускается одной командой: для запуска важны содержимое, описание точки входа и доступные зависимости.'),
    ('Surefire', 'Подключаемое средство Maven для выполнения модульных тестов и формирования отчётов. Его правила выбора проверок и настройки исполнения влияют на то, что фактически было проверено в фазе test.'),
    ('JUnit', 'Семейство средств для описания и выполнения автоматических тестов в экосистеме Java. Сам механизм выполнения тестов следует отличать от XML-отчёта, который затем читает Jenkins или другая система.'),
    ('Groovy', 'Язык программирования для JVM, используемый также при описании конвейеров Jenkins. Встроенные правила и преобразования Jenkins означают, что такой конвейер нельзя полностью понимать как произвольный обычный сценарий Groovy.'),
    ('ORIG_HEAD', 'Служебное имя Git, в котором некоторые операции сохраняют прежнюю позицию HEAD перед существенным изменением. Следующая подходящая операция может заменить это значение, поэтому оно не является самостоятельным бессрочным журналом восстановления.'),
]


def card(name, purpose, syntax, chapter, forms, url):
    return dict(name=name, purpose=purpose, syntax=syntax, chapter=chapter, volume='git',
                aliases=[], situations=[], source=url,
                sources=[dict(title='Официальная документация', url=url)],
                flags=[dict(flag=f, action=a, when=w, example=e, result=r)
                       for f, a, w, e, r in forms])


