    ('-m ТЕКСТ', 'Передать сообщение без открытия редактора.', 'Зафиксировать законченный подготовленный шаг.', 'git commit -m "Explain the greeting"', 'Появляется новый коммит; неподготовленные правки остаются вне него.'),
